def mark_negation(tokens, negations=("not", "no", "never", "n't"), stops=(".", ",", "!", "?", "and", "but")):
    out, negated = [], False
    for t in tokens:
        if t in stops:
            negated = False
            out.append(t)
        elif negated:
            out.append("NOT_" + t)
        else:
            out.append(t)
            negated = t in negations
    return out

